commands.command:
/bin/zsh -lc 'if [ -d /tmp/miniqmt-tunnel.lock ]; then rm /tmp/miniqmt-tunnel.lock/pid 2>/dev/null || true; rmdir /tmp/miniqmt-tunnel.lock 2>/dev/null || true; fi
launchctl bootstrap gui/$(id -u) /Users/oopslink/Library/LaunchAgents/com.miniqmt.tunnel.plist 2>&1 || true
sleep 3
echo launchctl_list
launchctl list | rg '"'miniqmt|tunnel|autossh' || true
echo counts
echo total="'$(ps -axo pid= | wc -l | tr -d '"' ')
echo oopslink="'$(ps -axo user= | awk '"'"'$1=="oopslink"{c++} END{print c+0}'"')
echo autossh_exact="'$(ps -axo command= | awk '"'/\\/opt\\/homebrew\\/bin\\/autossh -M 0 -N .* -L 8765:127\\.0\\.0\\.1:8765 oopslink@10\\.211\\.55\\.3/ {c++} END{print c+0}')
echo ssh_exact="'$(ps -axo command= | awk '"'/\\/usr\\/bin\\/ssh -N .*10\\.211\\.55\\.3/ {c++} END{print c+0}')
ps -axo pid=,ppid=,user=,stat=,etime=,command= | awk '/miniqmt-tunnel|autossh -M 0 -N|ssh -N .*10\\.211\\.55\\.3/ {print}'"
